{
  "nl": {
    "issue": [
      {
        "text": "合同生效后，当事人就质量、价款或者报酬、履行地点等内容没有约定或者约定不明确的，如何确定合同内容",
        "rules": ["c510-1", "c510-2"]
      },
      {
        "text": "行纪合同如何界定；行纪人与委托人之间关于费用负担、价格指示、自约权、提存、报酬与留置的权利义务",
        "rules": ["c951-def", "c952-1", "c955-1", "c955-1b", "c955-2", "c955-2b", "c955-3", "c956-1", "c956-2", "c957-1", "c957-1b", "c957-2", "c959-1", "c959-2"]
      }
    ],
    "conditions": [
      {
        "text": "合同已生效，且当事人就质量、价款或者报酬、履行地点等内容没有约定或者约定不明确",
        "rules": ["c510-1", "c510-2"]
      },
      {
        "text": "行纪人以自己的名义为委托人从事贸易活动，委托人支付报酬",
        "rules": ["c951-def"]
      },
      {
        "text": "行纪人处理委托事务支出费用",
        "rules": ["c952-1"]
      },
      {
        "text": "行纪人低于委托人指定的价格卖出，或者高于委托人指定的价格买入",
        "rules": ["c955-1", "c955-1b"]
      },
      {
        "text": "行纪人高于委托人指定的价格卖出，或者低于委托人指定的价格买入",
        "rules": ["c955-2", "c955-2b"]
      },
      {
        "text": "委托人对价格有特别指示",
        "rules": ["c955-3"]
      },
      {
        "text": "卖出或者买入的是具有市场定价的商品，且委托人无相反的意思表示",
        "rules": ["c956-1"]
      },
      {
        "text": "行纪人按照约定买入委托物；或者委托物不能卖出、委托人撤回出卖",
        "rules": ["c957-1", "c957-1b", "c957-2"]
      },
      {
        "text": "行纪人完成或者部分完成委托事务；委托人逾期不支付报酬",
        "rules": ["c959-1", "c959-2"]
      },
      {
        "text": "行纪人依委托人的指示从事贸易活动，并保管、合理处分委托物，报告和移交交易所得（笔记）",
        "rules": ["c951-instruct", "c951-custody"]
      },
      {
        "text": "行纪人与第三人订立合同的，由行纪人直接履行该合同（笔记）",
        "rules": ["c951-direct"]
      }
    ],
    "exceptions": [
      {
        "text": "当事人就处理委托事务的费用负担另有约定的，从其约定，行纪人不再负担",
        "rules": ["c952-exc"]
      },
      {
        "text": "当事人就留置权另有约定的，行纪人对委托物不享有留置权",
        "rules": ["c959-exc"]
      }
    ],
    "effects": [
      {
        "text": "当事人可以协议补充；不能达成补充协议的，按照合同相关条款或者交易习惯确定",
        "rules": ["c510-1", "c510-2"]
      },
      {
        "text": "行纪人处理委托事务支出的费用，由行纪人负担",
        "rules": ["c952-1"]
      },
      {
        "text": "低于指定价格卖出或高于指定价格买入的，应当经委托人同意；未经同意但行纪人补偿其差额的，该买卖对委托人发生效力",
        "rules": ["c955-1", "c955-1b"]
      },
      {
        "text": "高于指定价格卖出或低于指定价格买入的，可以按照约定增加报酬；没有约定或约定不明确且依第510条仍不能确定的，该利益属于委托人",
        "rules": ["c955-2", "c955-2b"]
      },
      {
        "text": "委托人对价格有特别指示的，行纪人不得违背该指示卖出或者买入",
        "rules": ["c955-3"]
      },
      {
        "text": "行纪人可以自己作为买受人或者出卖人，并仍然可以请求委托人支付报酬",
        "rules": ["c956-1", "c956-2"]
      },
      {
        "text": "委托人应当及时受领；经催告无正当理由拒绝受领，或委托物不能卖出、委托人撤回出卖经催告不取回、不处分的，行纪人依法可以提存委托物",
        "rules": ["c957-1", "c957-1b", "c957-2"]
      },
      {
        "text": "行纪人完成或者部分完成委托事务的，委托人应当支付相应报酬；逾期不支付的，行纪人对委托物享有留置权",
        "rules": ["c959-1", "c959-2"]
      }
    ],
    "priority": [
      {
        "text": "当事人另有约定时，排除行纪人负担费用、对委托物享有留置权的一般规则",
        "rules": ["c952-exc", "c959-exc"]
      },
      {
        "text": "委托人对价格有特别指示的，行纪人不得违背，优先于第955条第1款经委托人同意即可变通的一般规则",
        "rules": ["c955-3"]
      },
      {
        "text": "能达成补充协议的，优先按补充协议确定合同内容；不能达成时才按合同相关条款或者交易习惯确定",
        "rules": ["c510-1", "c510-2"]
      }
    ],
    "distinguish": [
      {
        "text": "行纪合同与委托合同：行纪人以自己的名义办理事务且限于商品寄售、购销等贸易活动；合同编未明确规定的，参照适用委托合同的规定（笔记）",
        "rules": ["c951-ref"]
      },
      {
        "text": "行纪合同与代理、居间：代理以被代理人名义，居间人不介入交易；行纪人以自己名义与第三人订约并直接履行（笔记、LEGO）",
        "rules": ["c951-direct"]
      },
      {
        "text": "笔记称行纪人仅限于经审查、登记可从事贸易活动的主体，法条未作此限定",
        "rules": []
      },
      {
        "text": "LEGO 卡片称行纪人违反保管义务或未报告、移交交易所得即不享有报酬请求权，法条无此限制，仅作参考",
        "rules": []
      }
    ]
  },
